"""Per-file acceptance filters for corpus ingestion."""

from __future__ import annotations

# Directories that never contain first-party source worth training on.
SKIP_DIRS: frozenset[str] = frozenset(
    {
        ".git",
        ".hg",
        ".svn",
        ".venv",
        "venv",
        "site-packages",
        "node_modules",
        "__pycache__",
        ".tox",
        ".mypy_cache",
        ".pytest_cache",
        ".ruff_cache",
        "dist",
        "build",
    }
)

GENERATED_MARKERS: tuple[str, ...] = (
    "auto-generated",
    "autogenerated",
    "automatically generated",
    "do not edit",
    "generated by",
)

# Minified or data-blob files have extremely long lines.
MAX_LINE_LENGTH = 1000


def load_text(data: bytes, max_bytes: int) -> tuple[str | None, str | None]:
    """Decide whether a file's bytes are acceptable training text.

    Returns ``(text, None)`` when acceptable, otherwise ``(None, reason)``
    where reason is one of: too-large, binary, not-utf8, empty, generated,
    long-lines.
    """
    if len(data) > max_bytes:
        return None, "too-large"
    if b"\x00" in data:
        return None, "binary"
    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError:
        return None, "not-utf8"
    text = text.lstrip("\ufeff").replace("\r\n", "\n").replace("\r", "\n")
    if not text.strip():
        return None, "empty"
    head = text[:512].lower()
    if any(marker in head for marker in GENERATED_MARKERS):
        return None, "generated"
    if max(len(line) for line in text.splitlines()) > MAX_LINE_LENGTH:
        return None, "long-lines"
    return text, None
